def generate_puzzle(n, center):
    """Generate output grid - two diagonals of 2s, with 1s at certain positions"""
    grid = [[0 for _ in range(n)] for _ in range(n)]

    # Fill 2s on both main diagonals and anti-diagonals
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            row = center + dy
            col = center + dx
            dist = max(abs(dy), abs(dx))  # Chebyshev distance

            if dist % 2 == 0:
                # Even distance shell - fill the axis-aligned positions
                if dy == 0 or dx == 0:
                    grid[row][col] = 2

    # At odd distances, create the diamond cross pattern
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            row = center + dy
            col = center + dx
            dist = max(abs(dy), abs(dx))

            if dist % 2 == 1:
                if abs(dy) == abs(dx) or dy == 0 or dx == 0:
                    grid[row][col] = 1

